begin
 select blueprint->'document' into v_new from public.island_starters where id='default';
 select p into v_sign from jsonb_array_elements(v_new->'layout')p where p->>'id'='wood-arrow-sign~starter-aquarium';
 if v_sign is null then raise exception 'AQUARIUM_STARTER_SIGN_REQUIRED';end if;
 v_x:=(v_sign->>'x')::integer;v_y:=(v_sign->>'y')::integer;
 select coalesce(jsonb_agg(p order by (p->>'x')::integer,(p->>'y')::integer),'[]') into v_old_grass from jsonb_array_elements(v_old->'paving')p where p->>'type'='grass';
 for v_profile in select * from app_private.player_islands order by user_id for update loop
  if exists(select 1 from app_private.player_island_items where user_id=v_profile.user_id and item_id='wood-arrow-sign' and sale_value=0) then continue;end if;
  v_id:='wood-arrow-sign~aquarium-welcome';
  insert into app_private.player_island_items(user_id,id,item_id,sale_value) values(v_profile.user_id,v_id,'wood-arrow-sign',0) on conflict do nothing;
  select coalesce(jsonb_agg(p order by (p->>'x')::integer,(p->>'y')::integer),'[]') into v_grass from jsonb_array_elements(v_profile.document->'paving')p where p->>'type'='grass';
  if v_grass=v_old_grass then
   v_doc:=jsonb_set(v_profile.document,'{paving}',(select coalesce(jsonb_agg(p.value order by p.ordinality),'[]') from jsonb_array_elements(v_profile.document->'paving') with ordinality p(value,ordinality) where p.value->>'type'<>'grass' or exists(select 1 from jsonb_array_elements(v_new->'paving')n where n=p.value)));
   if app_private.island_land_at(v_doc,v_x,v_y) and not exists(
    select 1 from jsonb_array_elements(v_doc->'layout')p
    left join app_private.player_island_items i on i.user_id=v_profile.user_id and i.id=p->>'id'
    join public.island_shop_items c on c.id=coalesce(i.item_id,p->>'id')
    where (p->>'x')::integer<=v_x and (p->>'y')::integer<=v_y
     and (p->>'x')::integer+case when coalesce((p->>'rotation')::integer,0)%180=90 then c.height else c.width end>v_x
     and (p->>'y')::integer+case when coalesce((p->>'rotation')::integer,0)%180=90 then c.width else c.height end>v_y
   ) then v_doc:=jsonb_set(v_doc,'{layout}',(v_doc->'layout')||jsonb_build_array(v_sign||jsonb_build_object('id',v_id)));end if;
   update app_private.player_islands set document=v_doc,revision=revision+1,updated_at=now() where user_id=v_profile.user_id;
  end if;
 end loop;
end $refresh$;
commit;
